{"file_path":"src/parser.js","content":"// Parser for the configuration document format described in the task.
//
// Produces a tree of tagged nodes:
//   { type: 'table', map: Map<string, Node>, path: string[], headered: bool }
//   { type: 'array-table', items: Node[] }        // items are 'table' nodes
//   { type: 'array', items: Node[] }
//   { type: 'string', value: string }
//   { type: 'integer', value: BigInt }
//   { type: 'float', value: number }
//   { type: 'boolean', value: boolean }

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.isParseError = true
    this.line = line
    this.reason = reason
  }
}

function mkErr(line, reason) {
  return new ParseError(line, reason)
}

function renderPath(path) {
  return path.join('.')
}

function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.pos = 0
    this.lineNo = lineNo
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  skipWSAndComment() {
    this.skipWS()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
      this.pos = this.line.length
    }
  }
}

const INTEGER_RE = /^[+-]?[0-9](_?[0-9])*$/
const FLOAT_RE = /^[+-]?[0-9](_?[0-9])*(\.[0-9](_?[0-9])*([eE][+-]?[0-9](_?[0-9])*)?|[eE][+-]?[0-9](_?[0-9])*)$/

function normalizeInt(word) {
  let w = word.replace(/_/g, '')
  if (w[0] === '+') w = w.slice(1)
  return BigInt(w)
}

function isStopChar(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

function parseBasicString(lp) {
  // assumes lp.peek() === '"'
  lp.pos++
  let result = ''
  while (true) {
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
    const c = lp.line[lp.pos]
    if (c === '"') {
      lp.pos++
      return result
    }
    if (c === '\\') {
      lp.pos++
      if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
      const e = lp.line[lp.pos]
      switch (e) {
        case '"':
          result += '"'
          lp.pos++
          break
        case '\\':
          result += '\\'
          lp.pos++
          break
        case 'n':
          result += '\n'
          lp.pos++
          break
        case 't':
          result += '\t'
          lp.pos++
          break
        case 'r':
          result += '\r'
          lp.pos++
          break
        case '0':
          result += '\0'
          lp.pos++
          break
        case 'u': {
          const hexStart = lp.pos + 1
          if (hexStart + 4 > lp.line.length) throw mkErr(lp.lineNo, 'unterminated string')
          const hex = lp.line.slice(hexStart, hexStart + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw mkErr(lp.lineNo, 'invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          lp.pos = hexStart + 4
          break
        }
        default:
          throw mkErr(lp.lineNo, `invalid escape \\${e}`)
      }
      continue
    }
    result += c
    lp.pos++
  }
}

function parseLiteralString(lp) {
  // assumes lp.peek() === "'"
  lp.pos++
  let result = ''
  while (true) {
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
    const c = lp.line[lp.pos]
    if (c === "'") {
      lp.pos++
      return result
    }
    result += c
    lp.pos++
  }
}

function parseName(lp) {
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a name')
  const c = lp.peek()
  if (c === '"') return parseBasicString(lp)
  if (c === "'") return parseLiteralString(lp)
  const start = lp.pos
  while (!lp.atEnd() && /[A-Za-z0-9_-]/.test(lp.peek())) lp.pos++
  if (lp.pos === start) throw mkErr(lp.lineNo, 'expected a name')
  return lp.line.slice(start, lp.pos)
}

function parseDottedName(lp) {
  const names = []
  while (true) {
    lp.skipWSAndComment()
    const name = parseName(lp)
    names.push(name)
    lp.skipWSAndComment()
    if (!lp.atEnd() && lp.peek() === '.') {
      lp.pos++
      lp.skipWSAndComment()
      continue
    }
    break
  }
  return names
}

function parseValue(lp, pathPrefix) {
  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a value')
  const c = lp.peek()
  if (c === '"') return { type: 'string', value: parseBasicString(lp) }
  if (c === "'") return { type: 'string', value: parseLiteralString(lp) }
  if (c === '[') return parseArray(lp)
  if (c === '{') return parseInlineTable(lp, pathPrefix)
  const start = lp.pos
  while (!lp.atEnd() && !isStopChar(lp.peek())) lp.pos++
  const word = lp.line.slice(start, lp.pos)
  if (word === 'true') return { type: 'boolean', value: true }
  if (word === 'false') return { type: 'boolean', value: false }
  if (INTEGER_RE.test(word)) return { type: 'integer', value: normalizeInt(word) }
  if (FLOAT_RE.test(word)) return { type: 'float', value: Number(word.replace(/_/g, '')) }
  throw mkErr(lp.lineNo, `invalid value ${word}`)
}

function parseArray(lp) {
  lp.pos++ // consume '['
  const items = []
  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated array')
  if (lp.peek() === ']') {
    lp.pos++
    return { type: 'array', items }
  }
  while (true) {
    const v = parseValue(lp, [])
    items.push(v)
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated array')
    if (lp.peek() === ',') {
      lp.pos++
      lp.skipWSAndComment()
      if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated array')
      if (lp.peek() === ']') {
        lp.pos++
        break
      }
      continue
    }
    if (lp.peek() === ']') {
      lp.pos++
      break
    }
    throw mkErr(lp.lineNo, 'unterminated array')
  }
  return { type: 'array', items }
}

function assignDotted(container, names, value, lineNo) {
  let t = container
  let path = container.path
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = path.concat(name)
    const entry = t.map.get(name)
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path, headered: false }
      t.map.set(name, nt)
      t = nt
    } else if (entry.type === 'table') {
      t = entry
    } else if (entry.type === 'array-table') {
      t = entry.items[entry.items.length - 1]
    } else {
      throw mkErr(lineNo, `${renderPath(path)} is not a table`)
    }
  }
  const last = names[names.length - 1]
  const finalPath = path.concat(last)
  if (t.map.has(last)) {
    throw mkErr(lineNo, `key ${renderPath(finalPath)} is defined twice`)
  }
  t.map.set(last, value)
}

function parseInlineTable(lp, pathPrefix) {
  lp.pos++ // consume '{'
  const table = { type: 'table', map: new Map(), path: pathPrefix, headered: true }
  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
  if (lp.peek() === '}') {
    lp.pos++
    return table
  }
  while (true) {
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== '=') throw mkErr(lp.lineNo, 'expected = in an inline table')
    lp.pos++
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a value')
    const fullPath = pathPrefix.concat(names)
    const value = parseValue(lp, fullPath)
    assignDotted(table, names, value, lp.lineNo)
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
    if (lp.peek() === ',') {
      lp.pos++
      continue
    }
    if (lp.peek() === '}') {
      lp.pos++
      break
    }
    throw mkErr(lp.lineNo, 'unterminated inline table')
  }
  return table
}

function walkIntermediateForHeader(root, names, lineNo) {
  let t = root
  let path = []
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = path.concat(name)
    const entry = t.map.get(name)
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path, headered: false }
      t.map.set(name, nt)
      t = nt
    } else if (entry.type === 'table') {
      t = entry
    } else if (entry.type === 'array-table') {
      t = entry.items[entry.items.length - 1]
    } else {
      throw mkErr(lineNo, `${renderPath(path)} is not a table`)
    }
  }
  return { table: t, path }
}

function handleHeader(state, names, isArray, lineNo) {
  const { table, path } = walkIntermediateForHeader(state.root, names, lineNo)
  const last = names[names.length - 1]
  const finalPath = path.concat(last)
  const entry = table.map.get(last)
  if (!isArray) {
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path: finalPath, headered: true }
      table.map.set(last, nt)
      state.current = nt
    } else if (entry.type === 'table') {
      if (entry.headered) throw mkErr(lineNo, `table ${renderPath(finalPath)} is defined twice`)
      entry.headered = true
      state.current = entry
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not a table`)
    }
  } else {
    if (entry === undefined) {
      const at = { type: 'array-table', items: [] }
      table.map.set(last, at)
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      at.items.push(item)
      state.current = item
    } else if (entry.type === 'array-table') {
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      entry.items.push(item)
      state.current = item
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not an array of tables`)
    }
  }
