{"file_path":"./src/lcs.js","content":"/**
 * Compute the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines (exact string comparison). When two
 * subsequences are equally long, ties are broken by preferring matches that
 * come earliest, walking both documents from the start and advancing the
 * side with the longer remaining subsequence, preferring to advance the
 * base when they tie.
 *
 * Returns a list of changes, each `{ baseStart, baseEnd, sideStart, sideEnd }`,
 * describing a run of base lines (possibly empty) replaced by a run of side
 * lines (possibly empty), ordered by position in the base.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const skipBase = dp[i + 1][j]
        const skipSide = dp[i][j + 1]
        dp[i][j] = skipBase >= skipSide ? skipBase : skipSide
      }
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let prevI = 0
  let prevJ = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (prevI < i || prevJ < j) {
        changes.push({ baseStart: prevI, baseEnd: i, sideStart: prevJ, sideEnd: j })
      }
      i++
      j++
      prevI = i
      prevJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, sideStart: prevJ, sideEnd: m })
  }
  return changes
}
"}

{"file_path":"./src/diff3.js","content":"import { computeChanges } from './lcs.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Given the changes touching a region that belong to one side, compute that
 * side's replacement lines for the region: from the smallest start of its
 * own changes, moved back by however far the region begins before those
 * changes do in the base, to the largest end of its own changes, moved
 * forward by however far the region ends after them.
 */
function resolveSide(regionBaseStart, regionBaseEnd, sideChanges, doc) {
  if (sideChanges.length === 0) return null
  let minChange = sideChanges[0]
  let maxChange = sideChanges[0]
  for (const c of sideChanges) {
    if (c.baseStart < minChange.baseStart) minChange = c
    if (c.baseEnd > maxChange.baseEnd) maxChange = c
  }
  const start = regionBaseStart + (minChange.sideStart - minChange.baseStart)
  const end = regionBaseEnd + (maxChange.sideEnd - maxChange.baseEnd)
  return doc.slice(start, end)
}

/**
 * Build the list of regions covering the whole base document, in order.
 * Each region is one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function diff3(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)

  const groups = []
  let i = 0
  while (i < all.length) {
    let baseStart = all[i].baseStart
    let baseEnd = all[i].baseEnd
    const changes = [all[i]]
    i++
    while (i < all.length && all[i].baseStart <= baseEnd) {
      changes.push(all[i])
      if (all[i].baseEnd > baseEnd) baseEnd = all[i].baseEnd
      i++
    }
    groups.push({ baseStart, baseEnd, changes })
  }

  const regions = []
  let pos = 0
  for (const g of groups) {
    if (pos < g.baseStart) {
      regions.push({ kind: 'stable', lines: base.slice(pos, g.baseStart) })
    }
    regions.push(resolveGroup(g, mine, base, theirs))
    pos = g.baseEnd
  }
  if (pos < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(pos, base.length) })
  }

  return regions
}

function resolveGroup(group, mine, base, theirs) {
  const { baseStart, baseEnd, changes } = group
  const mineChs = changes.filter(c => c.side === 'mine')
  const theirsChs = changes.filter(c => c.side === 'theirs')
  const baseLines = base.slice(baseStart, baseEnd)

  if (changes.length === 1) {
    const only = changes[0]
    const lines = only.side === 'mine' ? mine.slice(only.sideStart, only.sideEnd) : theirs.slice(only.sideStart, only.sideEnd)
    return { kind: only.side, lines }
  }

  const mineLines = resolveSide(baseStart, baseEnd, mineChs, mine) ?? baseLines
