 * Build the list of regions covering the whole base document, in order.
 * Each region is one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
