  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)

  const groups = []
  let i = 0
  while (i < all.length) {
    let baseStart = all[i].baseStart
    let baseEnd = all[i].baseEnd
    const changes = [all[i]]
    i++
    while (i < all.length && all[i].baseStart <= baseEnd) {
      changes.push(all[i])
      if (all[i].baseEnd > baseEnd) baseEnd = all[i].baseEnd
      i++
    }
    groups.push({ baseStart, baseEnd, changes })
  }

