{"file_path":"./src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { diff3 } from './diff3.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  return new Promise((resolve, reject) => {
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseInput(text) {
  const lines = splitLines(text)
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }
  if (docs.length !== 3) return null
  return docs
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const text = await readStdin()
  const docs = parseInput(text)
  if (docs === null) {
    fail('expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = docs

  const regions = diff3(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
      } else {
        out.push(`${region.kind} ${region.lines.length}`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine')
        for (const l of region.mine) out.push(l)
        if (mode === 'merge') {
          out.push('||||||| base')
          for (const l of region.base) out.push(l)
        }
        out.push('=======')
        for (const l of region.theirs) out.push(l)
        out.push('>>>>>>> theirs')
      } else {
        for (const l of region.lines) out.push(l)
      }
    }
  }

  const outputText = out.length > 0 ? `${out.join('\n')}\n` : ''
  process.stdout.write(outputText)
  process.exit(conflict ? 1 : 0)
}

main()
"}

