{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { countElection } from './election.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatRound(index, votes, exhausted) {
  const entries = [...votes.entries()]
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${index}: ${parts.join(' ')}`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = countElection(election.candidates, election.ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      output.push(formatRound(i + 1, round.votes, round.exhausted))
      if (round.eliminated !== null) {
        output.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }

  output.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(output.join('\n') + '\n')
  process.exit(0)
}

main()
"}

