{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parser.js'
import { checkCycle, computeTimings, computeWaves, computeTotal, computePriority, simulatePack } from './graph.js'
import { AppError, usageError, workersError } from './errors.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    const workersStr = argv[1]
    if (!/^[1-9][0-9]*$/.test(workersStr)) throw workersError()
    return { mode: 'pack', workers: parseInt(workersStr, 10) }
  }
  throw usageError()
}

async function main() {
  const argv = process.argv.slice(2)
  let args
  try {
    args = parseArgs(argv)
  } catch (err) {
    if (err instanceof AppError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.code)
    }
    throw err
  }

  const input = await readStdin()

  let tasks, deps
  try {
    ;({ tasks, deps } = parseGraph(input))
    checkCycle(tasks, deps)
  } catch (err) {
    if (err instanceof AppError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.code)
    }
    throw err
  }

  const timings = computeTimings(tasks, deps)
  const total = computeTotal(timings)

  if (args.mode === 'waves') {
    const waves = computeWaves(timings)
    const lines = waves.map((names, k) => `wave ${k}: ${names.join(' ')}`)
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (args.mode === 'explain') {
    const names = [...tasks.keys()].sort()
    const lines = names.map((name) => {
      const info = timings.get(name)
      return `${name} start=${info.start} finish=${info.finish} depth=${info.depth}`
    })
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (args.mode === 'pack') {
    const priority = computePriority(tasks, deps)
    const { workerLogs, makespan } = simulatePack(tasks, deps, priority, args.workers)
    const lines = workerLogs.map((log, i) => {
      const parts = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`)
