{"file_path":"src/parse.js","content":"/**
 * Parses the line-oriented election format described in the task: a
 * `candidates` declaration followed by any number of `ballot` records.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidateSet = new Set()
  const candidates = []
  let candidatesSeen = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = words.slice(1)
      if (rest.length === 0) {
        fail('expected candidates <name>...', lineNo)
      }
      for (const name of rest) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesSeen = true
    } else if (directive === 'ballot') {
      if (!candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = words.slice(1)
      if (rest.length < 2) {
        fail('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = rest[0]
      const names = rest.slice(1)
      if (!COUNT_RE.test(countStr)) {
        fail('count must be a positive integer', lineNo)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count: parseInt(countStr, 10), names })
    } else {
      fail(`unknown directive ${directive}`, lineNo)
    }
  }

  if (!candidatesSeen) {
    fail('no candidates', null)
  }

  return { candidates, ballots }
}

export { ParseError }
"}

{"file_path":"src/election.js","content":"/**
 * Runs the instant-runoff count described in the task, given the parsed
 * candidate list and ballots, producing a per-round trace and the winner.
 */

function tieBreak(tied, history) {
  let candidates = tied.slice()
  while (candidates.length > 1) {
    let separated = false
    for (const roundVotes of history) {
      const vals = candidates.map((c) => roundVotes.get(c))
      const uniq = new Set(vals)
      if (uniq.size > 1) {
        const min = Math.min(...vals)
        candidates = candidates.filter((c) => roundVotes.get(c) === min)
        separated = true
        break
      }
    }
    if (!separated) break
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.reduce((a, b) => (a > b ? a : b))
}

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    let exhausted = 0
    for (const ballot of ballots) {
      let picked = null
      for (const name of ballot.names) {
        if (continuing.has(name)) {
          picked = name
          break
        }
      }
      if (picked !== null) {
        votes.set(picked, votes.get(picked) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }
    history.push(votes)

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)
    let eliminated = null
    let roundWinner = null
    let noWinner = false

    if (activeTotal === 0) {
      noWinner = true
    } else {
      for (const [name, v] of votes) {
        if (v * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
      if (!roundWinner) {
        const minVotes = Math.min(...votes.values())
        const tied = [...votes.keys()].filter((k) => votes.get(k) === minVotes)
        eliminated = tied.length === 1 ? tied[0] : tieBreak(tied, history)
        continuing.delete(eliminated)
      }
    }

    rounds.push({ votes, exhausted, eliminated })

    if (roundWinner) {
      winner = roundWinner
      break
    }
    if (noWinner) {
      winner = null
      break
    }
    if (continuing.size === 0) {
      winner = null
      break
    }
  }

  return { rounds, winner }
}
"}

