    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = tokenize(source)
  } catch (e) {
    if (e instanceof ScanError) {
      process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) {
      const body = (t.kind === 'string' || t.kind === 'rawstring') ? JSON.stringify(t.text) : t.text
      out += `${t.line}:${t.col} ${t.kind} ${body}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    let out = ''
    for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${k} ${counts[k]}\n`
    }
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
  process.exit(0)
