{"file_path":"src/address.js","content":"// Column/address helpers shared across the sheet parser and the formula
// evaluator.

/** Convert 1 or 2 letters (A-Z) to a 1-based column index (A=1 .. ZZ=702). */
export function colToIndex(letters) {
  const s = letters.toUpperCase()
  if (s.length === 1) return s.charCodeAt(0) - 64
  const a = s.charCodeAt(0) - 64
  const b = s.charCodeAt(1) - 64
  return 26 + (a - 1) * 26 + b
}

/** Convert a 1-based column index back to its letters. */
export function indexToCol(idx) {
  if (idx <= 26) return String.fromCharCode(64 + idx)
  let n = idx - 26
  const a = Math.floor((n - 1) / 26) + 1
  const b = ((n - 1) % 26) + 1
  return String.fromCharCode(64 + a) + String.fromCharCode(64 + b)
}

/** Render a col/row pair back to its canonical address string. */
export function addressToString(col, row) {
  return indexToCol(col) + String(row)
}

/**
 * Match a bare address shape: 1-2 letters followed by 1-3 digits, case
 * insensitive. Returns { col, row } or null. Does not enforce row >= 1;
 * callers decide what that means in their context.
 */
export function matchAddressShape(str) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(str)
  if (!m) return null
  return { col: colToIndex(m[1]), row: parseInt(m[2], 10) }
}
"}

