/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { runLimiter } from './parser.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  try {
    while ((bytesRead = fs.readSync(fd, buf, 0, buf.length)) > 0) {
      chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
    }
  } catch (err) {
    if (err.code !== 'EAGAIN' && err.code !== 'EOF') throw err
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let result
  try {
    result = runLimiter(input)
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }

  const lines = []
  if (mode === 'replay') {
    for (const ev of result.events) {
      if (ev.allowed) {
        lines.push(`${ev.tick} ${ev.key} allow`)
      } else {
        lines.push(`${ev.tick} ${ev.key} deny ${ev.deniedBy}`)
      }
    }
  } else {
    const keys = [...result.summary.keys()].sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const s = result.summary.get(key)
      totalAllowed += s.allowed
      totalDenied += s.denied
      lines.push(`${key} allowed=${s.allowed} denied=${s.denied}`)
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

